const fs=require('fs'),path=require('path');
const files={
'frontend/public/editor.html':'',
'frontend/public/css/animations.css':'',
'frontend/public/css/canvas.css':'',
'frontend/public/css/editor.css':'',
'frontend/public/css/modal.css':'',
'frontend/public/css/panels.css':'',
'frontend/public/css/toolbar.css':'',
'frontend/public/js/ai-modal.js':'',
'frontend/public/js/canvas-elements.js':'',
'frontend/public/js/canvas.js':'',
'frontend/public/js/editor.js':'',
'frontend/public/js/panels.js':'',
'frontend/public/js/shortcuts.js':'',
'frontend/public/js/state.js':'',
'frontend/public/js/templates.js':'',
'frontend/public/js/toolbar.js':'',
'frontend/public/js/utils.js':'',
};
Object.entries(files).forEach(([d,b64])=>{
  const dir=path.dirname(d);if(!fs.existsSync(dir))fs.mkdirSync(dir,{recursive:true});
  fs.writeFileSync(d,Buffer.from(b64,'base64'));console.log('✅',d);
});console.log('Workspace navigation deployed!');